<?php
require_once __DIR__.'/config.php'; require_page_permission('persons');
if(isset($_GET['delete'])){$pdo->prepare('DELETE FROM persons WHERE id=?')->execute([(int)$_GET['delete']]);flash('شخص حذف شد.');redirect('persons.php');}
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)post('id');$d=[trim(post('first_name')),trim(post('last_name')),trim(post('national_code'))?:null,trim(post('mobile'))?:null,trim(post('phone'))?:null,trim(post('email'))?:null,trim(post('address'))?:null];if($id){$d[]=$id;$pdo->prepare('UPDATE persons SET first_name=?,last_name=?,national_code=?,mobile=?,phone=?,email=?,address=? WHERE id=?')->execute($d);flash('شخص ویرایش شد.');}else{$pdo->prepare('INSERT INTO persons(first_name,last_name,national_code,mobile,phone,email,address) VALUES(?,?,?,?,?,?,?)')->execute($d);flash('شخص اضافه شد.');}redirect('persons.php');}$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM persons WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}$rows=$pdo->query('SELECT * FROM persons ORDER BY id DESC')->fetchAll();page_header('اشخاص');
?><div class="toolbar"><h1>اشخاص</h1><a class="button" href="persons.php?new=1">+ شخص جدید</a></div><?php if(isset($_GET['new'])||$edit):?><form class="form" method="post"><?=csrf_field()?><?php if($edit):?><input type="hidden" name="id" value="<?=$edit['id']?>"><?php endif;?><div class="grid"><label>نام<input name="first_name" required value="<?=e($edit['first_name']??'')?>"></label><label>نام خانوادگی<input name="last_name" required value="<?=e($edit['last_name']??'')?>"></label><label>کد ملی<input name="national_code" value="<?=e($edit['national_code']??'')?>"></label><label>موبایل<input name="mobile" value="<?=e($edit['mobile']??'')?>"></label><label>تلفن<input name="phone" value="<?=e($edit['phone']??'')?>"></label><label>ایمیل<input type="email" name="email" value="<?=e($edit['email']??'')?>"></label><label style="grid-column:1/-1">آدرس<textarea name="address"><?=e($edit['address']??'')?></textarea></label></div><div class="actions"><button>ذخیره</button><a class="button" href="persons.php">انصراف</a></div></form><hr><?php endif;?><div class="table-wrap"><table class="table"><tr><th>نام</th><th>کد ملی</th><th>موبایل</th><th>ایمیل</th><th>عملیات</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['first_name'].' '.$r['last_name'])?></td><td><?=e($r['national_code'])?></td><td><?=e($r['mobile'])?></td><td><?=e($r['email'])?></td><td><a class="button" href="persons.php?edit=<?=$r['id']?>">ویرایش</a> <a class="button danger" onclick="return confirm('حذف شود؟')" href="persons.php?delete=<?=$r['id']?>">حذف</a></td></tr><?php endforeach;?></table></div><?php page_footer();?>
